import { UnsupportedOperationError } from "../errors.js";
import { setDataForToggleOne, setDataForUpdateOneOrAdd, } from "../helpers/queryData.js";
import { version } from "../version.js";
export class AdapterBase {
    _inited = true;
    adapterOpts = {
        numberId: false,
        idKey: "_id",
    };
    smartExecutor = false;
    capabilities = {
        transactions: false,
        indexes: false,
        persistent: true,
    };
    version = "AdapterBase-core-" + version;
    async init(...args) { }
    async close(...args) { }
    async beginTransaction(id, collections) {
        throw new UnsupportedOperationError("beginTransaction");
    }
    async commitTransaction(handle) {
        throw new UnsupportedOperationError("commitTransaction");
    }
    async rollbackTransaction(handle) {
        throw new UnsupportedOperationError("rollbackTransaction");
    }
    async createIndex(config) {
        // No-op: adapter does not use indexes internally
    }
    async removeIndex(config) {
        // No-op: adapter does not use indexes internally
    }
    async updateOneOrAdd(config) {
        const res = await this.updateOne(config);
        if (res)
            return {
                data: res,
                type: "updated",
            };
        // transform UpdateOneQuery to AddQuery
        setDataForUpdateOneOrAdd(config);
        return {
            data: await this.add(config),
            type: "added",
        };
    }
    async toggleOne(config) {
        const res = await this.removeOne(config);
        if (res)
            return {
                data: res,
                type: "removed",
            };
        // transform ToggleOneQuery to AddQuery
        setDataForToggleOne(config);
        return {
            data: await this.add(config),
            type: "added",
        };
    }
    async count(config) {
        const { collection, search, control, transaction } = config;
        const data = await this.find({
            collection,
            search: search ?? {},
            control,
            transaction,
        });
        return data.length;
    }
    async bulkAdd(config) {
        const results = [];
        for (const item of config.datas) {
            const result = await this.add({
                collection: config.collection,
                data: item,
                id_gen: config.id_gen,
                control: config.control,
                transaction: config.transaction,
            });
            results.push(result);
        }
        return results;
    }
}
