import { Collection, resolveCollection, } from "@wxn0brp/db-core/helpers/collection";
import { ResultPromise } from "@wxn0brp/db-core/helpers/resultPromise";
import { BaseRemote } from "./base.js";
/**
 * Represents a database management class for performing CRUD operations.
 * Uses a remote database.
 */
export class ValtheraRemote extends BaseRemote {
    /**
     * Create a new instance of a CollectionManager class.
     */
    c(collection) {
        return new Collection(this, collection);
    }
    /**
     * Get the names of all available databases.
     */
    getCollections() {
        return this._request("getCollections");
    }
    /**
     * Check and create the specified collection if it doesn't exist.
     */
    ensureCollection(target) {
        return this._request("ensureCollection", {
            collection: resolveCollection(target),
        });
    }
    /**
     * Check if a collection exists.
     */
    issetCollection(target) {
        return this._request("issetCollection", {
            collection: resolveCollection(target),
        });
    }
    /**
     * Add data to a database.
     */
    add(query) {
        return this._request("add", query);
    }
    /**
     * Find data in a database.
     */
    find(query) {
        return this._find(query);
    }
    /**
     * Find one data entry in a database.
     */
    findOne(query) {
        return this._findOne(query);
    }
    /**
     * Update data in a database.
     */
    update(query) {
        return this._request("update", query);
    }
    /**
     * Update one data entry in a database.
     */
    updateOne(query) {
        return this._request("updateOne", query);
    }
    /**
     * Remove data from a database.
     */
    remove(query) {
        return this._request("remove", query);
    }
    /**
     * Remove one data entry from a database.
     */
    removeOne(query) {
        return this._request("removeOne", query);
    }
    /**
     * Asynchronously updates one entry in a database or adds a new one if it doesn't exist.
     */
    updateOneOrAdd(query) {
        return ResultPromise.wrap(this._request("updateOneOrAdd", query));
    }
    /**
     * Asynchronously removes one entry in a database or adds a new one if it doesn't exist. Usage e.g. for toggling a flag.
     */
    toggleOne(query) {
        return ResultPromise.wrap(this._request("toggleOne", query));
    }
    /**
     * Removes a database collection from the file system.
     */
    removeCollection(target) {
        return this._request("removeCollection", {
            collection: resolveCollection(target),
        });
    }
    async createIndex() { }
    async removeIndex() { }
    count(query) {
        return this._request("count", query);
    }
    bulkAdd(query) {
        return this._request("bulkAdd", query);
    }
    capabilities() {
        return this._request("capabilities");
    }
}
